{{{{{1<noinclude>|Ability data</noinclude>}}}|Unraveled Earth|{{{2|}}}|{{{3|}}}|{{{4|}}}|{{{5|}}}
|champion     = Taliyah
|skill        = E
|icon         = Unraveled Earth.png
|blurb        = {{sbc|Active:}} {{ci|Taliyah}} scatters a field of stones in the target direction that deals {{as|magic damage}} to enemies hit. The stones remain for a few seconds and {{tip|slow}} enemies within.
|blurb2      = Enemies that {{tip|dash}} or are {{tip|airborne|knocked}} into a stone will detonate it, dealing {{as|magic damage}} and {{tip|stun|stunning}} them for a short time.
|description  = {{sbc|Active:}} '''Taliyah''' scatters a field of 22 stones across the ground in the target direction that deals {{as|magic damage}} to enemies hit while they erupt. The stones then remain for 4 seconds and {{tip|slow}} enemies within the area by 20%.
|leveling     = {{st|Magic Damage|{{ap|70 to 250}} {{as|(+ 70% AP)}}}}
|description2 = Enemies that {{tip|dash}} or are {{tip|airborne|knocked}} over a stone will detonate it, taking {{as|magic damage}} and becoming {{tip|stun|stunned}} for {{fd|0.75}} seconds, increased to 2 seconds if they are a {{tip|monster}}. The stun is applied once the displacement ends.
|leveling2    = {{st|Detonation Magic Damage|{{ap|30 to 90}} {{as|(+ 30% AP)}}}}
|description3 = An enemy can detonate up to 4 stones, but the damage is reduced by {{pp|changedisplay=true|key=%|type=stones detonated|0 to 75 for 4}}. ''Unraveled Earth'' can affect targets only once per cast; the stones will still detonate but not apply their effects.
|leveling3    = {{st|Total Maximum Detonation Damage|{{ap|30*(1+0.75+0.5+0.25) to 90*(1+0.75+0.5+0.25)}} {{as|(+ 75% AP)}}}}
|description4 = ''Unraveled Earth'' deals 225% damage against {{tip|monsters}}.
|cooldown     = 14
|cost         = 90
|costtype     = Mana
|effect radius= 800
|angle        = {{tt|80{{degree}}|Estimated}}
|cast time    = {{fd|0.25}}
|queue time   = {{fd|0.5}}
|targeting    = Direction
|affects      = Enemies
|damagetype   = magic
|spellshield  = true
|projectile   = false
|spelleffects = spellaoe
|notes        = 
* ''Unraveled Earth'' fires 6 rows of stones: the first row has 2 stones, and the rest have 4 each.
** The stones spawn in rows that cascade in {{fd|0.17}} second intervals.
* ''Unraveled Earth'' will not detonate if the target dashes over the stones while being untargetable.
* ''Unraveled Earth'' will not detonate against enemies that blink onto the stones.
{{Effect at cast time start}}
}}

{{{{{1<noinclude>|Ability data</noinclude>}}}|Threaded Volley|{{{2|}}}|{{{3|}}}|{{{4|}}}|{{{5|}}}
|champion     = Taliyah
|skill        = Q
|icon         = Threaded Volley.png
|blurb        = {{sbc|Active:}} {{ci|Taliyah}} barrages out 5 ''Stone Shards'' that each explode upon the first enemy hit, dealing {{as|magic damage}} to nearby enemies. This also creates an area of {{as|Worked Ground|terrain}} under '''Taliyah's''' location that lasts for a while. 
|blurb2      = Casting ''Threaded Volley'' on {{as|Worked Ground|terrain}} will consume the area to become empowered with a new effect as well as reduced {{sti|{{as|mana cost}}}} and {{sti|cooldown}}.
|blurb3      = {{sbc|Empowered Active:}} '''Taliyah''' hurls a ''Boulder'' that explodes upon the first enemy hit, dealing {{as|magic damage}} and briefly {{tip|slow|slowing}} nearby enemies. The first enemy hit takes {{ccs|increased|magic}} damage from the ''Boulder''.
|blurb4      = '''Taliyah''' can move and cast other abilities while launching ''Stone Shards''.
|description  = {{sbc|Active:}} '''Taliyah''' barrages 5 ''Stone Shards'' in the target direction over {{fd|1.5}} seconds that each shatter upon the first enemy hit, dealing {{as|magic damage}} to nearby enemies and {{tip|standard sight|revealing}} them for {{fd|0.5}} seconds. Subsequent hits deal 40% damage.
|leveling     = {{st|Magic Damage|{{ap|55 to 125}} {{as|(+ 50% AP)}}|Reduced Damage|{{ap|55*0.4 to 125*0.4}} {{as|(+ {{ap|50*0.4}}% AP)}}|Total Magic Damage|{{ap|55*2.6 to 125*2.6}} {{as|(+ 130% AP)}}}}
|description2 = '''Taliyah''' can move and cast other abilities while launching ''Stone Shards'', and is unable to basic attack until she launches the third ''Stone Shard''.
|description3 = Casting ''Threaded Volley'' creates an area of {{as|Worked Ground|terrain}} at '''Taliyah's''' cast location that has a radius of 400 units and lasts 30 seconds. While '''Taliyah''' is within an area of {{as|Worked Ground|terrain}}, ''Threaded Volley's'' cast consumes the area to become empowered with a new effect, costing {{sti|{{as|10 mana}}}} and having {{sti|cd|50%}} reduced cooldown, though not below {{fd|0.75}} seconds.
|icon4        = Threaded Volley 2.png
|description4 = {{sbc|Empowered Active:}} '''Taliyah''' hurls a ''Boulder'' that explodes upon the first enemy hit, dealing {{ccs|180%|magic}} damage to them and normal damage to nearby enemies, {{tip|slow|slowing}} all targets hit for {{fd|1.5}} seconds, and {{tip|standard sight|revealing}} them for {{fd|0.5}} seconds. {{tip|Monsters}} hit are also {{tip|stun|stunned}} for 3 seconds.
|leveling4    = {{st|Empowered Damage|{{ap|55*1.8 to 125*1.8}} {{as|(+ {{ap|50*1.8}}% AP)}}|Secondary Target Damage|{{ap|55 to 125}} {{as|(+ 50% AP)}}}}
{{st|Slow|{{ap|20 to 40}}%}}
|description5 = Against {{tip|monsters}}, ''Threaded Volley'' deals {{as|'''bonus''' magic damage}} per ''Stone Shard'', and the ''Boulder'' from the empowered cast deals 80% '''bonus''' damage against the primary target. This '''bonus''' damage is unaffected by the damage modifier from subsequent hits.
|leveling5    = {{st|Bonus Monster Damage|{{ap|20 to 40}}|Boulder Bonus Monster Damage|{{ap|20*1.8 to 40*1.8}}}}
|cooldown     = {{ap|7 to 3}}
|cost         = {{ap|55 to 75}}
|costtype     = Mana
|cast time    = {{fd|0.25}}
|effect radius= {{dv|{{tip|cr|icononly = true}} {{tt|175|Stone Shard radius}}|{{tip|cr|icononly = true}} {{tt|225|Boulder radius}}}}
|range        = {{tip|cr|icononly = true}} {{tt|1000|From Taliyah, when each missile is launched. Missiles originate 50 units in front of Taliyah}}
|width        = {{tip|er|icononly = true}} {{tt|200|Missile width, no offset to either side}}
|speed        = {{dv|{{tt|3600 - 1800|5000 units per second² deceleration, minimum is 1500 speed but it reaches its destination earlier than it can slow down to it}}|{{tt|2000|Empowered missile}}}}
|queue time   = {{fd|0.5}}
|targeting    = Direction
|affects      = Enemies
|damagetype   = magic
|projectile   = true
|spellshield  = Special
|spelleffects = special
|notes        = 
* ''Threaded Volley'' will continue casting while in {{tip|stasis}}.
* The first ''Stone Shard'' hit on each target is considered {{tip|area damage}}, while additional ones of the same cast are considered {{tip|persistent area damage}}.
** The ''Boulder'' applies {{tip|area damage}}.
* The first ''Stone Shard'' is launched instantly after the cast time ends, then the second and third ''Stone Shards'' are both launched over 1 second, and finally the fourth and fifth ''Stone Shards'' are both launched over {{fd|0.5}} seconds. 
* {{tip|Spell shield}} only prevents one instance of damage.
|flavorsound  = {{sm2|Taliyah_Original_Q_5.ogg}} ''"If at first you don't succeed, '''throw another rock'''!"''
}}

